package org.slavicmyths.skim;
import java.util.*;
import net.minecraft.core.*;
import net.minecraft.nbt.*;
import net.minecraft.server.level.*;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.block.Blocks;
import net.minecraft.world.level.saveddata.SavedData;
import net.minecraft.world.phys.Vec3;
import net.minecraft.world.item.*;
public final class SkimValley extends SavedData {
 public enum Status {BUILDING,READY,STARTING,ACTIVE,VICTORY,COMPLETE,BLOCKED}
 public static final class Entry {
  public UUID id=UUID.randomUUID(),owner,boss,hero;public BlockPos center;public int rotation,cursor;public Status status=Status.BUILDING;public long victoryAt,lastPlayerAt;public BlockPos bossPos;public boolean loot;public final Map<Long,String> expected=new HashMap<>();public final Set<Long> rocks=new HashSet<>();public final Set<UUID> participants=new HashSet<>();
  public Entry(BlockPos at,int rot){center=at;rotation=rot;}
  public BlockPos at(int x,int y,int z){return switch(Math.floorMod(rotation,4)){case 1->center.offset(-z,y,x);case 2->center.offset(-x,y,-z);case 3->center.offset(z,y,-x);default->center.offset(x,y,z);};}
  public boolean inside(Vec3 p,int r){return Math.abs(p.x-center.getX()-.5)<=r&&Math.abs(p.z-center.getZ()-.5)<=r;}
  public CompoundTag save(){var n=new CompoundTag();n.putUUID("Id",id);if(owner!=null)n.putUUID("Owner",owner);if(boss!=null)n.putUUID("Boss",boss);if(hero!=null)n.putUUID("Hero",hero);n.putLong("Center",center.asLong());n.putInt("Rotation",rotation);n.putInt("Cursor",cursor);n.putString("Status",status.name());n.putLong("VictoryAt",victoryAt);n.putLong("LastPlayerAt",lastPlayerAt);if(bossPos!=null)n.putLong("BossPos",bossPos.asLong());n.putBoolean("LootInstalled",loot);var a=new ListTag();expected.forEach((k,v)->{var t=new CompoundTag();t.putLong("Pos",k);t.putString("State",v);a.add(t);});n.put("Expected",a);n.putLongArray("Rocks",rocks.stream().mapToLong(Long::longValue).toArray());var ps=new ListTag();participants.forEach(p->ps.add(StringTag.valueOf(p.toString())));n.put("Participants",ps);return n;}
  public static Entry load(CompoundTag n){var e=new Entry(BlockPos.of(n.getLong("Center")),n.getInt("Rotation"));e.id=n.getUUID("Id");if(n.hasUUID("Owner"))e.owner=n.getUUID("Owner");if(n.hasUUID("Boss"))e.boss=n.getUUID("Boss");if(n.hasUUID("Hero"))e.hero=n.getUUID("Hero");try{e.status=Status.valueOf(n.getString("Status"));}catch(Exception ignored){e.status=Status.BLOCKED;}e.cursor=n.getInt("Cursor");e.victoryAt=n.getLong("VictoryAt");e.lastPlayerAt=n.getLong("LastPlayerAt");e.bossPos=n.contains("BossPos")?BlockPos.of(n.getLong("BossPos")):e.at(0,1,-20);e.loot=n.getBoolean("LootInstalled");for(var t:n.getList("Expected",Tag.TAG_COMPOUND)){var a=(CompoundTag)t;e.expected.put(a.getLong("Pos"),a.getString("State"));}for(long v:n.getLongArray("Rocks"))e.rocks.add(v);for(var t:n.getList("Participants",Tag.TAG_STRING))try{e.participants.add(UUID.fromString(t.getAsString()));}catch(Exception ignored){}return e;}
 }
 public final Map<UUID,Entry> valleys=new LinkedHashMap<>();public final Map<UUID,CompoundTag> progress=new HashMap<>();private final Set<UUID> jobs=new HashSet<>();private boolean restored;
 public static SkimValley get(ServerLevel w){return w.getServer().overworld().getDataStorage().computeIfAbsent(new Factory<>(SkimValley::new,SkimValley::load),"slavicmyths_skim_valley_173");}
 public static SkimValley load(CompoundTag n,HolderLookup.Provider p){var d=new SkimValley();for(var t:n.getList("Valleys",Tag.TAG_COMPOUND)){var e=Entry.load((CompoundTag)t);d.valleys.put(e.id,e);if(e.status==Status.BUILDING||e.status==Status.VICTORY)d.jobs.add(e.id);}for(var t:n.getList("Progress",Tag.TAG_COMPOUND)){var a=(CompoundTag)t;d.progress.put(a.getUUID("Player"),a);}d.restored=true;return d;}
 @Override public CompoundTag save(CompoundTag n,HolderLookup.Provider p){var a=new ListTag();valleys.values().forEach(e->a.add(e.save()));n.put("Valleys",a);var h=new ListTag();progress.values().forEach(h::add);n.put("Progress",h);return n;}
 public Entry near(Vec3 p){return valleys.values().stream().filter(e->e.inside(p,36)).findFirst().orElse(null);}
 public Entry lock(UUID p){return valleys.values().stream().filter(e->(e.status==Status.ACTIVE||e.status==Status.STARTING)&&(p.equals(e.owner)||e.participants.contains(p))).findFirst().orElse(null);}
 public static boolean place(ServerPlayer p,BlockPos at,int rot){var w=p.serverLevel();var d=get(w);if(w.dimension()!=Level.OVERWORLD||at.getY()+16>=w.getMaxBuildHeight()||d.valleys.values().stream().anyMatch(e->e.center.distSqr(at)<110*110))return false;var e=new Entry(at,rot);var plan=ValleyBlueprint.plan();
  for(int x=-32;x<=32;x++)for(int z=-50;z<=32;z++){if(z<-32&&Math.abs(x)>7)continue;var q=e.at(x,0,z);if(!w.hasChunkAt(q)||!w.getWorldBorder().isWithinBounds(q)||!org.slavicmyths.sivka.SivkaWhistle.safeFloor(w,q)||w.getBlockEntity(q)!=null)return false;var floor=w.getBlockState(q);if(!(floor.is(Blocks.GRASS_BLOCK)||floor.is(Blocks.DIRT)||floor.is(Blocks.STONE)||floor.is(Blocks.ANDESITE)||floor.is(Blocks.COARSE_DIRT)||floor.is(Blocks.PODZOL)))return false;for(int y=1;y<=16;y++){var a=q.above(y);if(!w.getFluidState(a).isEmpty()||(!w.getBlockState(a).isAir()&&!w.getBlockState(a).canBeReplaced())||w.getBlockEntity(a)!=null)return false;}}
  for(var cell:plan){var q=e.at(cell.at().getX(),cell.at().getY(),cell.at().getZ());if(!w.hasChunkAt(q)||!w.mayInteract(p,q)||w.getBlockEntity(q)!=null||(!w.getFluidState(q).isEmpty()))return false;var old=w.getBlockState(q);if(cell.at().getY()<0&&!(old.is(Blocks.DIRT)||old.is(Blocks.STONE)||old.is(Blocks.GRASS_BLOCK)||old.is(Blocks.ANDESITE)))return false;var event=new net.neoforged.neoforge.event.level.BlockEvent.BreakEvent(w,q,old,p);if(net.neoforged.neoforge.common.NeoForge.EVENT_BUS.post(event).isCanceled())return false;e.expected.put(q.asLong(),old.toString());if(cell.state().is(Blocks.ANDESITE)&&cell.at().getY()>0&&((Math.abs(cell.at().getX()-18)<=2&&Math.abs(cell.at().getZ()-5)<=2)||(Math.abs(cell.at().getX()+19)<=2&&Math.abs(cell.at().getZ()+10)<=2)))e.rocks.add(q.asLong());}
  d.valleys.put(e.id,e);d.jobs.add(e.id);d.setDirty();return true;
 }
 public static boolean start(ServerPlayer p){var w=p.serverLevel();var d=get(w);var e=d.near(p.position());if(!p.isAlive()||p.isSpectator()||w.dimension()!=Level.OVERWORLD||e==null||!w.getBlockState(e.at(0,0,27)).is(Blocks.CHISELED_STONE_BRICKS)||p.distanceToSqr(e.at(0,1,27).getCenter())>25){HeroCalls.message(p,"horn.wrong_place");return false;}if(e.status!=Status.READY||d.lock(p.getUUID())!=null||org.slavicmyths.bogatyr.BogatyrLedger.active(p)||org.slavicmyths.marinka.WitchYard.get(w).lock(p.getUUID())!=null){HeroCalls.message(p,"horn.active");return false;}var h=HeroCalls.loaded(p,"alyosha_popovich");if(!(h instanceof AlyoshaEntity a)||h.level()!=w||!a.isAlive()||a.recovering()||h.distanceToSqr(p)>18*18){HeroCalls.message(p,"summon.need_alyosha");return false;}
  var at=e.at(0,1,-20);var b=SkimContent.SKIM.get().create(w);if(b==null||!w.hasChunkAt(at)||!w.noCollision(new net.minecraft.world.phys.AABB(at.getX()-1.05,at.getY(),at.getZ()-1.05,at.getX()+1.05,at.getY()+2.95,at.getZ()+1.05)))return false;
  // Only session owner's matched hero fights. Existing other allies are parked outside the south approach.
  for(var id:List.of("ilya_muromets","dobrynya_nikitich")){var other=HeroCalls.loaded(p,id);if(other!=null&&other.level()==w){var outside=org.slavicmyths.bogatyr.BogatyrLedger.safe(w,e.at(0,1,38).getCenter(),other.getBbWidth(),other.getBbHeight(),3);if(outside==null){HeroCalls.message(p,"summon.unsafe");return false;}other.teleportTo(outside.x,outside.y,outside.z);}}
  b.moveTo(at.getX()+.5,at.getY(),at.getZ()+.5,rotYaw(e.rotation),0);b.arena=e.id;b.owner=p.getUUID();b.begin(SkimAction.AWAKEN);if(!org.slavicmyths.sivka.SivkaWhistle.safeFloor(w,at.below())||!w.noCollision(b,b.getBoundingBox()))return false;if(!w.addFreshEntity(b))return false;e.owner=p.getUUID();e.boss=b.getUUID();e.hero=a.getUUID();e.status=Status.STARTING;e.lastPlayerAt=w.getGameTime();e.bossPos=at;d.jobs.add(e.id);e.participants.clear();e.participants.add(p.getUUID());a.bind(e);d.setDirty();p.sendSystemMessage(net.minecraft.network.chat.Component.translatable("message.slavicmyths.skim.start"));return true;
 }
 private static float rotYaw(int r){return r*90F;}
 public static void abort(ServerLevel w,Entry e){if(e.boss!=null&&w.getEntity(e.boss) instanceof SkimBeastEntity b){b.release();b.discard();}if(e.hero!=null&&w.getEntity(e.hero) instanceof AlyoshaEntity h)h.arena=null;e.status=Status.READY;e.boss=null;e.owner=null;e.participants.clear();get(w).jobs.remove(e.id);get(w).setDirty();}
 public static void win(ServerLevel w,Entry e,SkimBeastEntity b){if(e==null||e.status!=Status.ACTIVE)return;var d=get(w);for(var p:w.getPlayers(p->!p.isCreative()&&!p.isSpectator()&&e.inside(p.position(),32)&&(b.contributors.contains(p.getUUID())||b.attendance.getOrDefault(p.getUUID(),0)>=60))){var n=d.progress.computeIfAbsent(p.getUUID(),k->new CompoundTag());if(n.getString("LastEncounter").equals(b.encounter.toString()))continue;n.putUUID("Player",p.getUUID());n.putBoolean("skim_beast_defeated",true);n.putBoolean("slavicmyths.skim_beast.story_defeated",true);n.putInt("defeat_count",n.getInt("defeat_count")+1);if(!n.contains("first_defeat_time"))n.putLong("first_defeat_time",w.getGameTime());n.putLong("last_defeat_time",w.getGameTime());n.putBoolean("ally_participation_alyosha",e.hero!=null);n.putBoolean("eligibleForFutureRewards",true);n.putBoolean("participationFlag",true);var party=new ListTag();if(e.hero!=null)party.add(StringTag.valueOf("alyosha_popovich"));n.put("last_party_ids",party);n.put("usedHeroIds",party.copy());n.putString("LastEncounter",b.encounter.toString());org.slavicmyths.rewards.RewardLedger.victory(p,2);}e.status=Status.VICTORY;e.victoryAt=w.getGameTime();d.jobs.add(e.id);d.setDirty();if(e.hero!=null&&w.getEntity(e.hero) instanceof AlyoshaEntity h){h.arena=null;h.cue("alyosha.victory");}}
 public void tick(ServerLevel w){if(w.dimension()!=Level.OVERWORLD)return;if(restored){for(var e:valleys.values())if(e.status==Status.ACTIVE||e.status==Status.STARTING)abort(w,e);restored=false;}
  for(var id:new ArrayList<>(jobs)){var e=valleys.get(id);if(e==null){jobs.remove(id);continue;}if(e.status==Status.ACTIVE||e.status==Status.STARTING){if(w.getGameTime()%60==0){for(var player:e.participants){var p=w.getServer().getPlayerList().getPlayer(player);if(p!=null&&p.isAlive()&&!p.isCreative()&&!p.isSpectator()&&p.level()==w&&e.inside(p.position(),32)){e.lastPlayerAt=w.getGameTime();break;}}if(w.getGameTime()-e.lastPlayerAt>1200||(e.bossPos!=null&&w.hasChunkAt(e.bossPos)&&!(w.getEntity(e.boss) instanceof SkimBeastEntity b&&b.isAlive())))abort(w,e);setDirty();}continue;}if(e.status==Status.BUILDING){var plan=ValleyBlueprint.plan();for(int budget=0;budget<256&&e.cursor<plan.size();budget++){var cell=plan.get(e.cursor);var q=e.at(cell.at().getX(),cell.at().getY(),cell.at().getZ());if(!w.hasChunkAt(q))break;if(!w.getBlockState(q).toString().equals(e.expected.get(q.asLong()))&&!w.getBlockState(q).equals(cell.state())){e.status=Status.BLOCKED;break;}w.setBlock(q,cell.state(),3);e.cursor++;}if(e.cursor>=plan.size()){boolean loaded=true;for(var q:List.of(e.at(4,1,-43),e.at(-4,1,-46)))loaded&=w.hasChunkAt(q)&&w.getBlockEntity(q) instanceof net.minecraft.world.level.block.entity.ChestBlockEntity;if(!loaded)continue;if(!e.loot){for(var q:List.of(e.at(4,1,-43),e.at(-4,1,-46))){var chest=(net.minecraft.world.level.block.entity.ChestBlockEntity)w.getBlockEntity(q);chest.setItem(0,new ItemStack(Items.BONE,12));chest.setItem(3,new ItemStack(Items.ARROW,16));chest.setItem(7,new ItemStack(Items.BREAD,4));chest.setItem(12,new ItemStack(Items.IRON_INGOT,3));chest.setChanged();}e.loot=true;}e.status=Status.READY;e.expected.clear();}if(e.status!=Status.BUILDING)jobs.remove(id);setDirty();}
   else if(e.status==Status.VICTORY&&w.getGameTime()-e.victoryAt>=75){boolean loaded=true;for(int x=-3;x<=3;x++)loaded&=w.hasChunkAt(e.at(x,1,-30));if(!loaded)continue;for(int x=-3;x<=3;x++)for(int y=1;y<=5;y++){var q=e.at(x,y,-30);if(w.getBlockState(q).is(Blocks.CRACKED_STONE_BRICKS))w.setBlock(q,Blocks.AIR.defaultBlockState(),3);}e.status=Status.COMPLETE;e.boss=null;e.owner=null;e.participants.clear();jobs.remove(id);w.playSound(null,e.at(0,1,-30),SkimContent.sound("arena.den_stone_open"),net.minecraft.sounds.SoundSource.BLOCKS,1,1);setDirty();}
  }
 }
}
